def render_table(columns, rows):
    template = Template("""
    &lt;table>
      &lt;thead>
        &lt;tr>
          {%- for column in columns %}
            &lt;th>{{ column }}&lt;/th>
          {%- endfor %}
        &lt;/tr>
      &lt;/thead>
      &lt;tbody>
        {%- for row in rows %}
          &lt;tr>
            {%- for cell in row %}
              &lt;td>{{ cell }}&lt;/td>
            {%- endfor %}
          &lt;/tr>
        {%- endfor %}
      &lt;/tbody>
    &lt;/table>
    """, autoescape=True)
    return template.render(columns=columns, rows=rows)

