import os
import json

orders = [
    {'id': '1', 'items': ['widget', 'gizmo']},
    {'id': '2', 'items': ['sprocket', 'thingamajig']}
]

def write_order(order, directory):
    path = os.path.join(directory, order['id'] + '.txt')
    with open(path, 'w') as f:
        f.write(json.dumps(order))

def process_orders(orders):
    order_dir = 'orders'

    if not os.path.exists(order_dir):
        os.makedirs(order_dir)

    for order in orders:
        write_order(order, order_dir)

process_orders(orders)

