from pathlib import Path

PART_EXT = '.part'

def path_for_part(num):
    return Path('parts') / f'part-{num}{PART_EXT}'

def cleanup_parts(num_parts):
    for i in range(num_parts+1, 100):
        path = path_for_part(i)
        if path.exists():
            path.unlink()

if __name__ == '__main__':
    num_parts = 10
    cleanup_parts(num_parts)

