import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/ride_details', methods=['POST'])
def ride_details():
    ride_id = request.form['ride_id']

    with sqlite3.connect('rides.db') as conn:
        cursor = conn.cursor()

        query = "SELECT * FROM rides WHERE id = ?"
        cursor.execute(query, [ride_id])
        ride = cursor.fetchone()

        if ride:
            return jsonify(ride)
        else:
            return jsonify({'error': 'Ride not found'})

if __name__ == '__main__':
    app.run()

