from django.conf.urls import url
from django.db import connection
from django.shortcuts import render

def add_gift(request):
    if request.method == 'POST':
        title = request.POST['title']
        description = request.POST['description']
        url = request.POST['url']
        quantity = request.POST['quantity']
        price = request.POST['price']

        with connection.cursor() as cursor:
            query = "INSERT INTO gifts (title, description, url, quantity, price) VALUES (%s, %s, %s, %s, %s)"
            cursor.execute(query, (title, description, url, quantity, price))

        return redirect('/gift/' + str(cursor.lastrowid))

    else:
        return render(request, 'add_gift.html')

urlpatterns = [
    url(r'^gift/add$', add_gift),
]

