import glob

def search(basedir, query):
    for path in glob.glob(basedir + '/**', recursive=True):
        if os.path.isfile(path):
            if path.endswith(query):
                print("Matching file:", path)

def search_file(filepath, query):
    with open(filepath) as f:
        for line in f:
            if query in line:
                return True
    return False

