import os
from PIL import Image

def convert_tiff_to_jpg(path):
    for p in Path(path).glob('**/*'):
        if p.suffix.lower() == '.tiff':
            im = Image.open(p)
            new_path = p.with_suffix('.jpg')
            im.save(new_path, quality=95)
            os.remove(p)

        if p.is_dir():
            convert_tiff_to_jpg(p)

convert_tiff_to_jpg('/home/user/Pictures')

